#!/usr/bin/env python3
"""Post-build step (make zyngui): add the zynthian widget to the LV2 bundle generated by DPF.

DPF rewrites the bundle's TTL files on every build (make gen), so this runs after it, idempotently:
- copies the widget files from zyngui/ (.py, .html and assets) into the bundle,
- appends zyngui/zyngui.ttl (the zyngui:widget declaration) to manifest.ttl,
- inserts zyngui/port_extras.json lines into <symbol>_dsp.ttl: zynthian metadata DPF can't express
  ({"port_symbol": ["lv2:displayPriority 100", ...], "group:group_symbol": [...]}).

usage: zyngui_bundle.py bin/<symbol>.lv2
"""

import json
import os
import re
import shutil
import sys

MARK = "# --- zynthian widget (added by tools/zyngui_bundle.py) ---"
ASSETS = (".py", ".html", ".css", ".png", ".svg", ".jpg")


def insert_after(text, anchor_re, lines, start=0):
    """Insert lines (TTL statements) after the line matching anchor_re, with its indentation.
    Lines already present right after it are not inserted again. Returns (text, found)."""
    m = re.compile(anchor_re, re.M).search(text, start)
    if not m:
        return text, False
    indent = m.group(1)
    new = []
    following = text[m.end():m.end() + 4096]
    for line in lines:
        stmt = f"{indent}{line.strip().rstrip(';').rstrip()} ;\n"
        if stmt not in following:
            new.append(stmt)
    return text[:m.end()] + "".join(new) + text[m.end():], True


def main():
    if len(sys.argv) != 2:
        print(__doc__)
        return 1
    bundle = sys.argv[1].rstrip("/")
    symbol = os.path.basename(bundle)[:-len(".lv2")]
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    zdir = os.path.join(root, "zyngui")
    manifest = os.path.join(bundle, "manifest.ttl")
    if not os.path.isfile(manifest):
        print(f"ERROR: {manifest} not found (run make gen first)")
        return 1

    # Widget files
    for fname in sorted(os.listdir(zdir)):
        if fname.endswith(ASSETS):
            shutil.copy2(os.path.join(zdir, fname), os.path.join(bundle, fname))

    # zyngui:widget declaration
    with open(manifest) as f:
        ttl = f.read()
    if MARK not in ttl:
        with open(os.path.join(zdir, "zyngui.ttl")) as f:
            ttl = ttl.rstrip("\n") + f"\n\n{MARK}\n" + f.read()
        with open(manifest, "w") as f:
            f.write(ttl)

    # Port & group extras
    extras_path = os.path.join(zdir, "port_extras.json")
    if os.path.isfile(extras_path):
        with open(extras_path) as f:
            extras = json.load(f)
        dsp = os.path.join(bundle, f"{symbol}_dsp.ttl")
        with open(dsp) as f:
            ttl = f.read()
        for key, lines in extras.items():
            if key.startswith("_"):
                continue  # comments
            if key.startswith("group:"):
                gsym = key[len("group:"):]
                head = ttl.find(f"#portGroup_{gsym}>\n")
                if head < 0:
                    print(f"WARNING: port group '{gsym}' not found in {dsp}")
                    continue
                # In the group block, lv2:symbol ends the statement (" ."): insert after lv2:name
                ttl, found = insert_after(ttl, r'^(\s*)lv2:name "[^"\n]*" ;\n', lines, head)
            else:
                ttl, found = insert_after(ttl, r'^(\s*)lv2:symbol "%s" ;\n' % re.escape(key), lines)
            if not found:
                print(f"WARNING: '{key}' not found in {dsp}")
        with open(dsp, "w") as f:
            f.write(ttl)

    print(f"zynthian widget added to {bundle}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
